    Object.assign(pageCopy.pa,{weekday:'ਪਸੰਦੀਦਾ ਹਫ਼ਤੇ ਦਾ ਦਿਨ',weekdayEmpty:'ਦਿਨ ਵੇਖਣ ਲਈ ਮਿਤੀ ਚੁਣੋ',visitDate:'ਪਸੰਦੀਦਾ ਮਿਤੀ',visitTime:'ਪਸੰਦੀਦਾ ਸਮਾਂ'});
