    const siteClock=document.querySelector('#site-clock');let serverClockOffset=0;
    function updateSiteClock(){if(!siteClock)return;const now=new Date(Date.now()+serverClockOffset),locale={en:'en-IN',pa:'pa-IN',hi:'hi-IN'}[currentLanguage]||'en-IN';siteClock.dateTime=now.toISOString();siteClock.textContent=`${pageCopy[currentLanguage].clockLabel} · ${new Intl.DateTimeFormat(locale,{timeZone:'Asia/Kolkata',dateStyle:'medium',timeStyle:'medium'}).format(now)} IST`}
    async function syncServerClock(){const started=Date.now();try{const response=await fetch(`${window.location.pathname}?clock=${Date.now()}`,{method:'HEAD',cache:'no-store'}),serverDate=response.headers.get('date');if(serverDate){const received=Date.now(),serverMilliseconds=Date.parse(serverDate);if(Number.isFinite(serverMilliseconds))serverClockOffset=serverMilliseconds+Math.round((received-started)/2)-received}}catch{}updateSiteClock()}
